package com.antra.notification; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.kafka.annotation.*;
@SpringBootApplication public class NotificationApplication {public static void main(String[] a){SpringApplication.run(NotificationApplication.class,a);}@KafkaListener(topics="reservation-created",groupId="notification") void reservation(Object event){System.out.println("Confirmation queued: "+event);}@KafkaListener(topics="payment-completed",groupId="notification") void payment(Object event){System.out.println("Payment receipt queued: "+event);}}
